    // Ensure n >= 2
    if (n < 2) {
        return false;
    }

    // Ensure tests vector is not empty
    if (tests.empty()) {
        return false;
    }

    // Remove duplicates from the tests vector
    auto last = std::unique(tests.begin(), tests.end());
    tests.erase(last, tests.end());

    // Ensure all test values are within the valid range [2, n-2]
    for (auto& a : tests) {
        if (!(2 <= a && a <= n - 2)) {
            return false;
        }
